Here is the commit message:
perf: Fix default aux_watermark calculation

The default aux_watermark is half the AUX area buffer size. In general,
on a 64-bit architecture, the AUX area buffer size could be a bigger than
fits in a 32-bit type, but the calculation does not allow for that
possibility.

However the aux_watermark value is recorded in a u32, so should not be
more than U32_MAX either.

Fix by doing the calculation in a correctly sized type, and limiting the
result to U32_MAX.

Fixes: d68e6799a5c8 ("perf: Cap allocation order at aux_watermark")
Signed-off-by: Adrian Hunter <adrian.hunter@intel.com>
Signed-off-by: Peter Zijlstra (Intel) <peterz@infradead.org>
Link: https://lore.kernel.org/r/20240624201101.60186-7-adrian.hunter@intel.com

Here is the root cause:
The bug arises from the calculation of the `watermark` variable, which is derived from the number of pages (`nr_pages`) and the page shift value (`PAGE_SHIFT`). On 64-bit architectures, the resulting value can exceed the maximum limit of a 32-bit unsigned integer (`U32_MAX`), leading to potential overflow issues. The original calculation did not account for this possibility, risking incorrect values being assigned to `watermark`, which is later used in memory allocation processes.

Here is the patch:

 int rb_alloc_aux(struct perf_buffer *rb, struct perf_event *event,
 		 pgoff_t pgoff, int nr_pages, long watermark, int flags)
 {
 	bool overwrite = !(flags & RING_BUFFER_WRITABLE);
 	int node = (event->cpu == -1) ? -1 : cpu_to_node(event->cpu);
 	int ret = -ENOMEM, max_order;

 	if (!has_aux(event))
 		return -EOPNOTSUPP;

 	if (!overwrite) {
 		/*
 		 * Watermark defaults to half the buffer, and so does the
 		 * max_order, to aid PMU drivers in double buffering.
 		 */
 		if (!watermark)
-			watermark = nr_pages << (PAGE_SHIFT - 1);
+			watermark = min_t(unsigned long,
+					  U32_MAX,
+					  (unsigned long)nr_pages << (PAGE_SHIFT - 1));

 		/*
 		 * Use aux_watermark as the basis for chunking to
 		 * help PMU drivers honor the watermark.
 		 */
 		max_order = get_order(watermark);
 	} else {
 		/*
 		 * We need to start with the max_order that fits in nr_pages,
 		 * not the other way around, hence ilog2() and not get_order.
 		 */
 		max_order = ilog2(nr_pages);
 		watermark = 0;
 	}

 	/*
 	 * kcalloc_node() is unable to allocate buffer if the size is larger
 	 * than: PAGE_SIZE << MAX_PAGE_ORDER; directly bail out in this case.
 	 */
 	if (get_order((unsigned long)nr_pages * sizeof(void *)) > MAX_PAGE_ORDER)
 		return -ENOMEM;
 	rb->aux_pages = kcalloc_node(nr_pages, sizeof(void *), GFP_KERNEL,
 				     node);
 	if (!rb->aux_pages)
 		return -ENOMEM;

 	rb->free_aux = event->pmu->free_aux;
 	for (rb->aux_nr_pages = 0; rb->aux_nr_pages < nr_pages;) {
 		struct page *page;
 		int last, order;

 		order = min(max_order, ilog2(nr_pages - rb->aux_nr_pages));
 		page = rb_alloc_aux_page(node, order);
 		if (!page)
 			goto out;

 		for (last = rb->aux_nr_pages + (1 << page_private(page));
 		     last > rb->aux_nr_pages; rb->aux_nr_pages++)
 			rb->aux_pages[rb->aux_nr_pages] = page_address(page++);
 	}

 	/*
 	 * In overwrite mode, PMUs that don't support SG may not handle more
 	 * than one contiguous allocation, since they rely on PMI to do double
 	 * buffering. In this case, the entire buffer has to be one contiguous
 	 * chunk.
 	 */
 	if ((event->pmu->capabilities & PERF_PMU_CAP_AUX_NO_SG) &&
 	    overwrite) {
 		struct page *page = virt_to_page(rb->aux_pages[0]);

 		if (page_private(page) != max_order)
 			goto out;
 	}

 	rb->aux_priv = event->pmu->setup_aux(event, rb->aux_pages, nr_pages,
 					     overwrite);
 	if (!rb->aux_priv)
 		goto out;

 	ret = 0;

 	/*
 	 * aux_pages (and pmu driver's private data, aux_priv) will be
 	 * referenced in both producer's and consumer's contexts, thus
 	 * we keep a refcount here to make sure either of the two can
 	 * reference them safely.
 	 */
 	refcount_set(&rb->aux_refcount, 1);

 	rb->aux_overwrite = overwrite;
 	rb->aux_watermark = watermark;

 out:
 	if (!ret)
 		rb->aux_pgoff = pgoff;
 	else
 		__rb_free_aux(rb);

 	return ret;
 }



